"""Headless real BT and magnet regression, restricted to locally generated bytes and loopback peers."""
from pathlib import Path
import hashlib, json, os, socket, struct, subprocess, sys, threading, time, urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
sys.stdout.reconfigure(encoding='utf-8')
root=Path(__file__).resolve().parent.parent
report=root/'reports'/('bt-'+time.strftime('%Y%m%d-%H%M%S'))
report.mkdir()
fixture=report/'fixtures'; fixture.mkdir()
seed=report/'seed'; seed.mkdir()
def bencode(value):
    if isinstance(value,int): return b'i'+str(value).encode()+b'e'
    if isinstance(value,str): value=value.encode('utf-8')
    if isinstance(value,bytes): return str(len(value)).encode()+b':'+value
    if isinstance(value,list): return b'l'+b''.join(map(bencode,value))+b'e'
    return b'd'+b''.join(bencode(k)+bencode(value[k]) for k in sorted(value))+b'e'
def free_port():
    with socket.socket() as s: s.bind(('127.0.0.1',0)); return s.getsockname()[1]
peer_port=free_port()
dead_peer=free_port()
(fixture/'dead-port.txt').write_text(str(dead_peer),encoding='ascii')
requests=[]
once_requests=0
once_counts={}
slow_stop_events=[]
class Tracker(BaseHTTPRequestHandler):
    def do_GET(self):
        global once_requests
        requests.append(self.path.split('?',1)[0])
        if self.path.startswith('/seed/'):
            path=(seed/urllib.parse.unquote(urllib.parse.urlsplit(self.path).path[len('/seed/'):])).resolve()
            if not path.is_relative_to(seed.resolve()) or not path.is_file():self.send_error(404);return
            content=path.read_bytes();start=0;end=len(content)-1
            requested=self.headers.get('Range','')
            if requested:
                bounds=requested.removeprefix('bytes=').split('-',1);start=int(bounds[0]);end=min(end,int(bounds[1]) if bounds[1] else end)
            self.send_response(206 if requested else 200);self.send_header('Content-Length',str(end-start+1));self.send_header('Accept-Ranges','bytes')
            if requested:self.send_header('Content-Range',f'bytes {start}-{end}/{len(content)}')
            self.end_headers();self.wfile.write(content[start:end+1]);return
        peers=b'' if self.path.startswith('/empty') else socket.inet_aton('127.0.0.1')+struct.pack('!H',dead_peer)+socket.inet_aton('127.0.0.1')+struct.pack('!H',peer_port)
        if self.path.startswith(('/once','/restart-once')):
            once_requests+=1
            key=self.path.split('?',1)[0];once_counts[key]=once_counts.get(key,0)+1
            if once_counts[key]>1:peers=b''
        if self.path.startswith('/slow-stop'):
            slow_stop_events.append('12-second delayed tracker '+urllib.parse.parse_qs(urllib.parse.urlsplit(self.path).query).get('event',['none'])[0]);time.sleep(12)
        body=bencode({'interval':2,'complete':1 if peers else 0,'incomplete':1,'peers':peers})
        self.send_response(200); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
    def log_message(self,*args): pass
tracker=ThreadingHTTPServer(('127.0.0.1',0),Tracker)
threading.Thread(target=tracker.serve_forever,daemon=True).start()
announce=f'http://127.0.0.1:{tracker.server_port}/announce'
data=(bytes(range(251))*(16*1024*1024//251+1))[:16*1024*1024]
name='本机BT检查'
paths=[['数据一.bin'],['子目录','数据二.bin']]
for index,parts in enumerate(paths):
    target=seed/name/Path(*parts); target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(data[index*8388608:(index+1)*8388608])
info={'name':name,'piece length':65536,'pieces':b''.join(hashlib.sha1(data[i:i+65536]).digest() for i in range(0,len(data),65536)), 'private':1,
      'files':[{'length':8388608,'path':p} for p in paths]}
document={'announce':announce,'info':info}
torrent=fixture/'local.torrent'; torrent.write_bytes(bencode(document))
(fixture/'resume-once.torrent').write_bytes(bencode({'announce':announce.replace('/announce','/once'),'info':info}))
(fixture/'restart-once.torrent').write_bytes(bencode({'announce':announce.replace('/announce','/restart-once'),'info':info}))
(fixture/'slow-stop.torrent').write_bytes(bencode({'announce':announce.replace('/announce','/slow-stop'),'url-list':[announce.replace('/announce','/seed/')],'info':info}))
cold_info=dict(info,name='等待节点检查')
cold=fixture/'cold.torrent'; cold.write_bytes(bencode({'announce':announce.replace('/announce','/empty'),'info':cold_info}))
for index in (2,3):
    (fixture/f'cold{index}.torrent').write_bytes(bencode({'announce':announce.replace('/announce','/empty'),'info':dict(cold_info,name='等待节点检查'+str(index))}))
public_info=dict(info,name='本机DHT检查'); public_info.pop('private')
for parts in paths:
    target=seed/public_info['name']/Path(*parts);target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes((seed/name/Path(*parts)).read_bytes())
public=fixture/'public.torrent'; public.write_bytes(bencode({'info':public_info}))
dht_magnet='magnet:?xt=urn:btih:'+hashlib.sha1(bencode(public_info)).hexdigest()
# A minimal BEP5 bootstrap returns only loopback nodes and the local seeder.
def bdecode(data):
    def read(at):
        marker=data[at:at+1]
        if marker==b'i':
            end=data.index(b'e',at); return int(data[at+1:end]),end+1
        if marker in (b'd',b'l'):
            result={} if marker==b'd' else []; at+=1
            while data[at:at+1]!=b'e':
                value,at=read(at)
                if isinstance(result,dict): other,at=read(at); result[value]=other
                else: result.append(value)
            return result,at+1
        end=data.index(b':',at); length=int(data[at:end]); return data[end+1:end+1+length],end+1+length
    return read(0)[0]
dht=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); dht.bind(('127.0.0.1',0));dht.settimeout(.2)
dht_port=dht.getsockname()[1];dht_queries=[];dht_stop=threading.Event()
def serve_dht():
    node_id=b'\x35'*20
    while not dht_stop.is_set():
        try: packet,source=dht.recvfrom(4096)
        except socket.timeout: continue
        except OSError: break
        try:
            request=bdecode(packet); query=request.get(b'q');dht_queries.append(query.decode())
            reply={'id':node_id}
            if query==b'find_node': reply['nodes']=node_id+socket.inet_aton('127.0.0.1')+struct.pack('!H',dht_port)
            elif query==b'get_peers': reply.update(token=b'local',values=[socket.inet_aton('127.0.0.1')+struct.pack('!H',peer_port)])
            dht.sendto(bencode({'t':request[b't'],'y':'r','r':reply}),source)
        except (ValueError,KeyError,IndexError): pass
threading.Thread(target=serve_dht,daemon=True).start()
boundary_name='边界BT检查'
boundary_lengths=[8388608+123,8388608-123]
offset=0
for parts,length in zip(paths,boundary_lengths):
    target=seed/boundary_name/Path(*parts); target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(data[offset:offset+length]); offset+=length
boundary_info=dict(info,name=boundary_name,files=[{'length':length,'path':p} for p,length in zip(paths,boundary_lengths)])
boundary=fixture/'boundary.torrent'; boundary.write_bytes(bencode({'announce':announce,'info':boundary_info}))
info_hash=hashlib.sha1(bencode(info)).hexdigest()
magnet='magnet:?xt=urn:btih:'+info_hash+'&dn='+urllib.parse.quote(name)+'&tr='+urllib.parse.quote(announce,safe='')
for suffix,change in [
    ('traversal',{'files':[{'length':len(data),'path':['..','escape.bin']}]}),
    ('absolute',{'files':[{'length':len(data),'path':['C:\\escape.bin']}]}),
    ('duplicate',{'files':[{'length':8388608,'path':['a.bin']},{'length':8388608,'path':['A.bin']}]}),
    ('reserved',{'name':'CON'}),('piece-count',{'pieces':b'x'*20}),
    ('symlink',{'files':[{'length':len(data),'path':['link'],'attr':'l'}]}),
    ('alternate-path',{'files':[{'length':len(data),'path':['..','escape.bin'],'path.utf-8':['safe.bin']}]}),
    ('alternate-name',{'name':'..','name.utf-8':'safe'}),
    ('prefix-conflict',{'files':[{'length':8388608,'path':['a']},{'length':8388608,'path':['a','b']}]}),
    ('v2-only',{'meta version':2,'pieces':None}),
    ('private-flag',{'private':'invalid'}),
]:
    bad=dict(info); bad.update(change)
    if bad.get('pieces') is None: bad.pop('pieces')
    (fixture/f'invalid-{suffix}.torrent').write_bytes(bencode({'info':bad}))
for suffix,body in [('duplicate-key',b'd4:infoi1e4:infoi2ee'),('depth',b'l'*40+b'e'*40),('truncated',b'd4:info')]:
    (fixture/f'invalid-{suffix}.torrent').write_bytes(body)
binary=report/'Bt.Check.exe'
compiler=Path(os.environ['WINDIR'])/'Microsoft.NET/Framework64/v4.0.30319/csc.exe'
refs=['System','System.Core','System.Security','System.Drawing','System.Windows.Forms','System.Web.Extensions','System.IO.Compression','System.IO.Compression.FileSystem','Microsoft.CSharp']
subprocess.run([str(compiler),'/nologo','/target:exe','/platform:x64','/utf8output','/main:BtCheck','/out:'+str(binary),*['/r:'+r+'.dll' for r in refs],*[str(root/'desktop'/s) for s in ['Shiying.cs','Window.cs','Plugin.cs','Components.cs','Install.cs','Details.cs','Torrent.cs','Netdisk.cs']],str(root/'scripts/bt-check.cs')],check=True,creationflags=subprocess.CREATE_NO_WINDOW)
import shutil
(report/'bin').mkdir(); shutil.copy2(root/'desktop/bin/aria2c.exe',report/'bin/aria2c.exe'); shutil.copy2(root/'desktop/components.json',report/'components.json')
seeder_args=[str(root/'desktop/bin/aria2c.exe'),'--no-conf=true','--no-netrc=true','--interface=127.0.0.1','--disable-ipv6=true','--enable-dht=false','--enable-dht6=false','--enable-peer-exchange=false','--bt-enable-lpd=false','--check-integrity=true','--seed-time=30','--seed-ratio=0.0','--listen-port='+str(peer_port),'--dir='+str(seed),'--console-log-level=notice','--bt-external-ip=127.0.0.1',str(torrent),str(boundary),str(public)]
with (report/'seeder.log').open('w',encoding='utf-8') as log:
    seeder=subprocess.Popen(seeder_args,stdout=log,stderr=subprocess.STDOUT,creationflags=subprocess.CREATE_NO_WINDOW)
    try:
        child=subprocess.Popen([str(binary),str(report),str(torrent),magnet,str(seed),str(boundary),str(cold),str(dht_port),dht_magnet,*sys.argv[1:]],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace',creationflags=subprocess.CREATE_NO_WINDOW)
        with (report/'check.log').open('w',encoding='utf-8') as check_log:
            for line in child.stdout:
                print(line,end='',flush=True); check_log.write(line); check_log.flush()
        code=child.wait()
        if code==0 and not sys.argv[1:]:
            for stage in ['restart-cache-save','restart-cache-load']:
                result=subprocess.run([str(binary),str(report),str(torrent),magnet,str(seed),str(boundary),str(cold),str(dht_port),dht_magnet,stage],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace',creationflags=subprocess.CREATE_NO_WINDOW)
                (report/(stage+'.log')).write_text(result.stdout,encoding='utf-8');print(result.stdout,flush=True)
                if result.returncode:code=result.returncode;break
            assert once_counts.get('/restart-once',0)>=2,'Separate processes must encounter the exhausted original tracker'
        if code==0:assert slow_stop_events,'Slow tracker regression must receive an actual delayed request'
    finally:
        seeder.terminate()
        try: seeder.wait(timeout=5)
        except subprocess.TimeoutExpired: seeder.kill(); seeder.wait()
        tracker.shutdown(); tracker.server_close();dht_stop.set();dht.close()
        (report/'network-scope.json').write_text(json.dumps({'tracker':announce,'seed':'127.0.0.1:'+str(peer_port),'requests':len(requests),'oneShotTrackerRequests':once_requests,'oneShotTrackerPaths':once_counts,'slowStopEvents':slow_stop_events,'dhtBootstrap':'127.0.0.1:'+str(dht_port),'dhtQueries':dht_queries,'publicNetworkUsed':False,'mediaDownloaded':False,'windowsShown':False},indent=2),encoding='utf-8')
print(json.dumps({'report':str(report),'exitCode':code},ensure_ascii=False))
raise SystemExit(code)
